exports.init = (params, rng) => {
  const gravity = params.gravity ?? 9.81;
  const dragCoeff = params.dragCoeff ?? 0.47;
  const mass = params.mass ?? 0.00001;
  const radius = params.radius ?? 0.001;
  const airDensity = params.airDensity ?? 1.2;
  const area = Math.PI * radius * radius;
  const weight = mass * gravity;
  return {
    t: 0,
    v: 0,
    yFallen: 0,
    netForce: weight,
    acceleration: gravity,
    drag: 0,
    gravity,
    dragCoeff,
    mass,
    radius,
    airDensity,
    area,
    weight,
    dt: 0.05,
    trail: []
  };
};

exports.step = (state, params, rng) => {
  const gravity = params.gravity ?? state.gravity;
  const dragCoeff = params.dragCoeff ?? state.dragCoeff;
  const mass = params.mass ?? state.mass;
  const radius = params.radius ?? state.radius;
  const airDensity = params.airDensity ?? state.airDensity;
  const area = Math.PI * radius * radius;
  const weight = mass * gravity;
  const dt = state.dt;
  const t = state.t + dt;
  const hasDrag = dragCoeff > 0 && airDensity > 0 && area > 0;
  let v, yFallen, drag, netForce, acceleration;
  if (!hasDrag) {
    v = gravity * t;
    yFallen = 0.5 * gravity * t * t;
    drag = 0;
    netForce = weight;
    acceleration = gravity;
  } else {
    const vt = Math.sqrt((2 * mass * gravity) / (dragCoeff * airDensity * area));
    const x = gravity * t / vt;
    if (x > 10) {
      v = vt;
      drag = weight;
      netForce = 0;
      acceleration = 0;
      yFallen = vt * t - (vt * vt / gravity) * Math.log(2);
    } else {
      const tanhX = Math.tanh(x);
      v = vt * tanhX;
      let lnCosh;
      if (x > 20) {
        lnCosh = x - Math.log(2);
      } else {
        lnCosh = Math.log(Math.cosh(x));
      }
      yFallen = (vt * vt / gravity) * lnCosh;
      drag = 0.5 * dragCoeff * airDensity * area * v * v;
      netForce = weight - drag;
      acceleration = netForce / mass;
      if (Math.abs(netForce) < 1e-12) netForce = 0;
      if (Math.abs(acceleration) < 1e-12) acceleration = 0;
    }
  }
  const towerH = 70;
  const topY = 85;
  const yOffset = yFallen % towerH;
  const screenY = topY - yOffset;
  let trail = state.trail ? state.trail.slice() : [];
  if (trail.length > 0) {
    const lastY = trail[trail.length - 1];
    if (screenY > lastY + 40) {
      trail = [];
    }
  }
  trail.push(screenY);
  if (trail.length > 7) trail.shift();
  return {
    t,
    v,
    yFallen,
    netForce,
    acceleration,
    drag,
    gravity,
    dragCoeff,
    mass,
    radius,
    airDensity,
    area,
    weight,
    dt,
    trail
  };
};

exports.observe = (state, params) => {
  return {
    velocity: state.v,
    netForce: state.netForce,
    terminalVelocity: state.v,
    height: state.yFallen,
    acceleration: state.acceleration
  };
};

exports.view = (state, params) => {
  const bounds = { x: 0, y: 0, w: 100, h: 100 };
  const towerH = 70;
  const topY = 85;
  const yOffset = state.yFallen % towerH;
  const y = topY - yOffset;
  const x = 50;
  const viewRadius = 4 + state.radius * 6000;
  const balancedThreshold = state.weight * 0.05;
  const absNet = Math.abs(state.netForce);
  let color;
  if (absNet < balancedThreshold) {
    color = "#4CAF50";
  } else if (state.netForce > 0) {
    color = "#FF9800";
  } else {
    color = "#2196F3";
  }
  const bodies = [];
  bodies.push({ id: "bg", x: 50, y: 50, radius: 75, color: "#E3F2FD" });
  bodies.push({ id: "ground", x: 50, y: 3, radius: 18, color: "#C8E6C9" });
  for (let i = 0; i < 8; i++) {
    const wy = 12 + i * 10;
    bodies.push({ id: "wallL" + i, x: 32, y: wy, radius: 1.2, color: "#B0BEC5" });
    bodies.push({ id: "wallR" + i, x: 68, y: wy, radius: 1.2, color: "#B0BEC5" });
  }
  for (let i = 0; i < 9; i++) {
    const sy = 10 + i * 10;
    bodies.push({ id: "track" + i, x: 85, y: sy, radius: 1, color: "#E0E0E0" });
  }
  const hasDrag = state.dragCoeff > 0 && state.airDensity > 0 && state.area > 0;
  let vt = 25;
  if (hasDrag) {
    vt = Math.sqrt((2 * state.mass * state.gravity) / (state.dragCoeff * state.airDensity * state.area));
    if (!isFinite(vt) || vt <= 0) vt = 25;
  }
  const maxV = hasDrag ? Math.max(vt, 12) : 30;
  const speedY = 10 + Math.min(1, state.v / maxV) * 80;
  bodies.push({ id: "speedMarker", x: 85, y: speedY, radius: 3.5, color: color });
  bodies.push({ id: "speedTop", x: 85, y: 90, radius: 1.5, color: "#90A4AE" });
  let trailColor;
  if (color === "#FF9800") trailColor = "#FFCC80";
  else if (color === "#4CAF50") trailColor = "#A5D6A7";
  else trailColor = "#90CAF9";
  if (state.trail) {
    for (let i = 0; i < state.trail.length - 1; i++) {
      const ty = state.trail[i];
      const age = i / state.trail.length;
      const r = 1.4 + age * 1.0;
      bodies.push({ id: "trail" + i, x: x, y: ty, radius: r, color: trailColor });
    }
  }
  const weightR = 2.8;
  const dragRatio = state.weight > 0 ? state.drag / state.weight : 0;
  const dragR = Math.max(0.5, Math.min(4, 2.8 * dragRatio));
  if (dragR > 0.6) {
    bodies.push({ id: "dragForce", x: x, y: y + 7, radius: dragR, color: "#42A5F5" });
  }
  bodies.push({ id: "weightForce", x: x, y: y - 7, radius: weightR, color: "#EF5350" });
  bodies.push({ id: "drop", x, y, radius: viewRadius, color });
  return { kind: "bodies", bounds, bodies };
};
